public object FfiConverterTypeKeystoreSigner: FfiConverter<KeystoreSigner, Long> {
    internal val handleMap = UniffiHandleMap<KeystoreSigner>()

    override fun lower(value: KeystoreSigner): Long {
        if (value is KeystoreSignerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): KeystoreSigner {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return KeystoreSignerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): KeystoreSigner {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: KeystoreSigner) = 8UL

    override fun write(value: KeystoreSigner, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
