/**
 * @suppress
 */
public object FfiConverterTypeWitness: FfiConverter<Witness, Long> {
    override fun lower(value: Witness): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Witness {
        return Witness(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Witness {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Witness) = 8UL

    override fun write(value: Witness, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



